package com.oyuki.marketsquare.entity; import com.oyuki.user.entity.User; import com.oyuki.marketsquare.enums.PriceUpdateStatus; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.LocalDateTime; @Entity @Table(name="market_price_updates") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class MarketPriceUpdate { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) @JoinColumn(name="market_id") private Market market; @ManyToOne(optional=false) @JoinColumn(name="agent_id") private User agent; private String productName; private String unit; private BigDecimal price; @Enumerated(EnumType.STRING) @Builder.Default private PriceUpdateStatus status=PriceUpdateStatus.PENDING; private LocalDateTime createdAt; private LocalDateTime approvedAt; @PrePersist void pre(){if(createdAt==null)createdAt=LocalDateTime.now();} }